<?php
namespace Tests\Feature;
use App\Models\User;
use App\Models\Task;
use App\Models\Workspace;
use App\Services\Identity;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\Storage;
use Illuminate\Http\UploadedFile;
use Tests\TestCase;
class TaskTest extends TestCase {
 use RefreshDatabase;
 private function login(User $u): static {return $this->actingAs($u)->withSession(['auth_version'=>$u->auth_version])->withoutVite();}
 private function makeTask(User $u,array $attributes=[]): Task {$w=Identity::personal($u);$t=new Task(array_merge(['title'=>'Test task','priority'=>'medium','status'=>'pending'],$attributes));$t->workspace_id=$w->id;$t->creator_id=$u->id;$t->save();return $t;}
 private function payload(array $extra=[]): array {return array_merge(['title'=>'New task','status'=>'pending','priority'=>'medium'],$extra);}
 public function test_guest_cannot_access_tasks(): void {$this->get('/tasks')->assertRedirect('/login');}
 public function test_create_edit_complete_and_delete(): void {$u=User::factory()->create();$this->login($u)->post('/tasks',$this->payload())->assertRedirect();$t=Task::firstOrFail();$this->assertSame($u->id,$t->creator_id);$this->get('/tasks/'.$t->id)->assertOk()->assertSee('New task');$this->put('/tasks/'.$t->id,$this->payload(['title'=>'Updated','status'=>'completed']))->assertRedirect();$this->assertNotNull($t->fresh()->completed_at);$this->delete('/tasks/'.$t->id)->assertRedirect('/tasks');$this->assertSoftDeleted($t);}
 public function test_foreign_task_access_and_mutation_denied(): void {$u=User::factory()->create();$other=User::factory()->create();$t=$this->makeTask($other,['title'=>'Private secret']);$this->login($u)->get('/tasks')->assertOk()->assertDontSee('Private secret');$this->get('/tasks/'.$t->id)->assertNotFound();$this->put('/tasks/'.$t->id,$this->payload())->assertNotFound();$this->delete('/tasks/'.$t->id)->assertNotFound();}
 public function test_business_workspace_cannot_create_personal_task(): void {$u=User::factory()->create();$w=Workspace::create(['owner_id'=>$u->id,'name'=>'Business','type'=>'business']);$this->login($u)->withSession(['workspace_id'=>$w->id])->post('/tasks',$this->payload())->assertForbidden();}
 public function test_cross_workspace_dependencies_and_parents_rejected(): void {$u=User::factory()->create();$other=User::factory()->create();$t=$this->makeTask($other);$this->login($u)->post('/tasks',$this->payload(['parent_id'=>$t->id]))->assertSessionHasErrors('parent_id');$this->post('/tasks',$this->payload(['dependencies'=>[$t->id]]))->assertSessionHasErrors('dependencies');}
 public function test_dependency_cycles_and_blocked_completion(): void {$u=User::factory()->create();$a=$this->makeTask($u);$b=$this->makeTask($u);$this->login($u)->put('/tasks/'.$a->id,$this->payload(['dependencies'=>[$b->id]]))->assertRedirect();$this->put('/tasks/'.$b->id,$this->payload(['dependencies'=>[$a->id]]))->assertSessionHasErrors('dependencies');$this->put('/tasks/'.$a->id,$this->payload(['dependencies'=>[$b->id],'status'=>'completed']))->assertSessionHasErrors('status');}
 public function test_due_date_converted_to_utc_and_today_filter(): void {$u=User::factory()->create(['timezone'=>'Asia/Dhaka']);$this->travelTo(\Illuminate\Support\Carbon::parse('2026-11-27 01:00 UTC'));$this->login($u)->post('/tasks',$this->payload(['due_at'=>'2026-11-27T12:30','title'=>'Local today']))->assertRedirect();$this->assertSame('2026-11-27 06:30:00',Task::firstOrFail()->due_at->format('Y-m-d H:i:s'));$this->get('/tasks?view=today')->assertOk()->assertSee('Local today');}
 public function test_recurrence_and_reminder_are_idempotent(): void {$u=User::factory()->create();$t=$this->makeTask($u,['recurrence'=>'daily','due_at'=>now()->subHour(),'remind_at'=>now()->subHours(2)]);$this->artisan('tasks:tick')->assertSuccessful();$this->artisan('tasks:tick')->assertSuccessful();$this->assertSame(1,Task::where('series_id',$t->id)->count());$this->assertSame(1,$t->history()->where('event','reminder_due')->count());}
 public function test_private_attachment_upload_download_and_isolation(): void {Storage::fake('local');$u=User::factory()->create();$other=User::factory()->create();$t=$this->makeTask($u);$this->login($u)->post('/tasks/'.$t->id.'/attachments',['file'=>UploadedFile::fake()->createWithContent('note.txt','private note')])->assertRedirect();$a=$t->attachments()->firstOrFail();Storage::disk('local')->assertExists($a->path);$url='/tasks/'.$t->id.'/attachments/'.$a->id;$this->get($url)->assertOk();$this->login($other)->get($url)->assertNotFound();}
 public function test_invalid_attachment_and_wrong_task_attachment_denied(): void {Storage::fake('local');$u=User::factory()->create();$t=$this->makeTask($u);$b=$this->makeTask($u);$this->login($u)->post('/tasks/'.$t->id.'/attachments',['file'=>UploadedFile::fake()->createWithContent('bad.php','<?php echo 1;')])->assertSessionHasErrors('file');$this->post('/tasks/'.$t->id.'/attachments',['file'=>UploadedFile::fake()->createWithContent('note.txt','hello')])->assertRedirect();$a=$t->attachments()->firstOrFail();$this->get('/tasks/'.$b->id.'/attachments/'.$a->id)->assertNotFound();}
 public function test_dashboard_metrics_and_task_views_render(): void {$u=User::factory()->create();$t=$this->makeTask($u,['title'=>'Visible task']);$this->login($u)->get('/dashboard')->assertOk()->assertSee('Open tasks');$this->get('/tasks?layout=board')->assertOk()->assertSee('Visible task');$this->get('/tasks/create')->assertOk();$this->get('/tasks/'.$t->id.'/edit')->assertOk();}
}
